import{_ as e,o,c as a,ag as r}from"./chunks/framework.B7PviQjB.js";const s="/docs/images/sheets/pivot-tables-editor.png",p=JSON.parse('{"title":"Summarize data with a pivot table","description":"Group and total a range of data on its own tab with a pivot table.","frontmatter":{"title":"Summarize data with a pivot table","description":"Group and total a range of data on its own tab with a pivot table.","type":"how-to"},"headers":[],"relativePath":"sheets/pivot-tables.md","filePath":"sheets/pivot-tables.md"}'),n={name:"sheets/pivot-tables.md"};function l(i,t,d,h,c,u){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="summarize-data-with-a-pivot-table" tabindex="-1">Summarize data with a pivot table <a class="header-anchor" href="#summarize-data-with-a-pivot-table" aria-label="Permalink to &quot;Summarize data with a pivot table&quot;">​</a></h1><p>Group and total a range of data on its own tab with a pivot table.</p><p>A pivot table is a snapshot: it recalculates only when you click <strong>Refresh pivot table</strong>, not when the source data changes.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need edit access.</li><li>Select at least 2 rows and 1 column. The first row must hold the column headers.</li><li>Pivot tables are created from the right-click menu only. There is no toolbar button.</li></ul></div><h2 id="create-a-pivot-table" tabindex="-1">Create a pivot table <a class="header-anchor" href="#create-a-pivot-table" aria-label="Permalink to &quot;Create a pivot table&quot;">​</a></h2><ol><li>Open the sheet and select the data, including the header row. For example, select <strong>A1:D50</strong>.</li><li>Right-click the selection and select <strong>Insert pivot table</strong>.</li></ol><p>A new tab named <strong>Pivot Table 1</strong> opens, with the <strong>Pivot table editor</strong> on the right. The tab stays empty until you add a value and refresh.</p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>Select the data, then touch and hold the selection to open the menu and select <strong>Insert pivot table</strong>.</p><h2 id="add-rows-columns-and-values" tabindex="-1">Add rows, columns, and values <a class="header-anchor" href="#add-rows-columns-and-values" aria-label="Permalink to &quot;Add rows, columns, and values&quot;">​</a></h2><ol><li>In the <strong>Pivot table editor</strong>, click <strong>Add</strong> under <strong>Rows</strong> and select a column to group by, such as <code>Region</code>.</li><li>To spread a second grouping across the top, click <strong>Add</strong> under <strong>Columns</strong> and select a column, such as <code>Quarter</code>.</li><li>Click <strong>Add</strong> under <strong>Values</strong> and select the column to total, such as <code>Revenue</code>.</li><li>Choose how to total it: <strong>SUM</strong>, <strong>COUNT</strong>, <strong>COUNTA</strong>, <strong>AVERAGE</strong>, <strong>MIN</strong>, or <strong>MAX</strong>. The default is <strong>SUM</strong>.</li><li>Click <strong>Refresh pivot table</strong>.</li></ol><p>The pivot tab fills with one row per group and a grand total. Add several row fields to nest groups. A column can sit in only one of <strong>Rows</strong>, <strong>Columns</strong>, and <strong>Filters</strong>, but you can add it to <strong>Values</strong> more than once, for example as both <strong>SUM</strong> and <strong>COUNT</strong>.</p><p><img src="'+s+'" alt="Pivot table grouping revenue by region and quarter, with the Pivot table editor open"></p><h3 id="change-the-sort-order-or-remove-a-field" tabindex="-1">Change the sort order or remove a field <a class="header-anchor" href="#change-the-sort-order-or-remove-a-field" aria-label="Permalink to &quot;Change the sort order or remove a field&quot;">​</a></h3><ul><li>Click the sort icon on a row or column field to switch between ascending and descending order.</li><li>Click <strong>✕</strong> on a field to remove it.</li></ul><p>Click <strong>Refresh pivot table</strong> after each change to see the result.</p><h2 id="refresh-after-the-source-data-changes" tabindex="-1">Refresh after the source data changes <a class="header-anchor" href="#refresh-after-the-source-data-changes" aria-label="Permalink to &quot;Refresh after the source data changes&quot;">​</a></h2><ol><li>Open the pivot tab. If the editor is closed, click <strong>Edit pivot table</strong> in the top right.</li><li>Click <strong>Refresh pivot table</strong>.</li></ol><p>The result is recalculated from the current source data.</p><h2 id="hide-grand-totals" tabindex="-1">Hide grand totals <a class="header-anchor" href="#hide-grand-totals" aria-label="Permalink to &quot;Hide grand totals&quot;">​</a></h2><ol><li>In the <strong>Pivot table editor</strong>, find <strong>Totals</strong>.</li><li>Clear <strong>Show row totals</strong> or <strong>Show column totals</strong>.</li><li>Click <strong>Refresh pivot table</strong>.</li></ol><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>The <strong>Filters</strong> area doesn&#39;t hide any values yet, and rows hidden by a filter are still counted. To pivot a subset, copy those rows to their own range and pivot that.</li><li>The pivot table reads the range you selected when you created it. Rows added below that range aren&#39;t included.</li><li>You can&#39;t type into the cells of a pivot tab or insert rows and columns there.</li><li><strong>Refresh pivot table</strong> stays unavailable until you add at least one value field.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/sheets/charts.html">Charts</a> to visualize the totals.</li><li><a href="/docs/sheets/sort-and-filter.html">Sort and filter</a> to explore the source data row by row.</li><li><a href="/docs/sheets/functions.html">Functions</a> such as <code>SUMIF</code> for totals that update on their own.</li></ul>',25)])])}const b=e(n,[["render",l]]);export{p as __pageData,b as default};
